package eventbus_test

import (
	"example.com/eventbusmod/eventbus"
	"fmt"
	"math/rand"
	"reflect"
)

var _ = fmt.Sprint
var _ = reflect.DeepEqual
var _ = rand.Intn

func reference(s eventbus.Outbox, lines []string) error {
	for _, line := range lines {
		s.Write(line)
		if err := s.Flush(); err != nil {
			return err
		}
	}
	return nil
}

type fakeSink struct {
	lines   []string
	flushes int
}

func (f *fakeSink) Write(line string) { f.lines = append(f.lines, line) }
func (f *fakeSink) Flush() error      { f.flushes++; return nil }

type input struct {
	f     *fakeSink
	lines []string
}

func genInput(rng *rand.Rand, big bool) input {
	n := rng.Intn(10)
	if big {
		n = 500
	}
	lines := make([]string, n)
	for i := range lines {
		lines[i] = fmt.Sprintf("event-%d", rng.Intn(1000))
	}
	return input{f: &fakeSink{}, lines: lines}
}

func (in input) run() error { return eventbus.PublishEvents(in.f, in.lines) }
func (in input) refRun() error { return reference(&fakeSink{}, in.lines) }

func callIt(in input) []string {
	if err := in.run(); err != nil {
		return []string{"error: " + err.Error()}
	}
	return in.f.lines
}

func refIt(in input) []string {
	other := &fakeSink{}
	if err := reference(other, in.lines); err != nil {
		return []string{"error: " + err.Error()}
	}
	return other.lines
}

func same(a, b any) bool {
	va, vb := reflect.ValueOf(a), reflect.ValueOf(b)
	if va.Kind() == reflect.Slice && vb.Kind() == reflect.Slice && va.Len() == 0 && vb.Len() == 0 {
		return true
	}
	return reflect.DeepEqual(a, b)
}

