package meters_test

import (
	"example.com/metersmod/meters"
	"fmt"
	"math/rand"
	"reflect"
)

var _ = fmt.Sprint
var _ = reflect.DeepEqual

func reference(s meters.Readings, queries [][2]int) []int {
	out := make([]int, 0, len(queries))
	for _, q := range queries {
		sum := 0
		for i := q[0]; i < q[1]; i++ {
			sum += s.At(i)
		}
		out = append(out, sum)
	}
	return out
}

type fakeSeries struct {
	data  []int
	reads int
}

func (f *fakeSeries) Len() int { return len(f.data) }
func (f *fakeSeries) At(i int) int {
	f.reads++
	return f.data[i]
}

type input struct {
	f *fakeSeries
	q [][2]int
}

func genInput(rng *rand.Rand, big bool) input {
	n, k := 1+rng.Intn(20), rng.Intn(6)
	if big {
		n, k = 2000, 60
	}
	data := make([]int, n)
	for i := range data {
		data[i] = rng.Intn(1000)
	}
	q := make([][2]int, k)
	for i := range q {
		lo := rng.Intn(n)
		hi := lo + rng.Intn(n-lo+1)
		q[i] = [2]int{lo, hi}
	}
	return input{f: &fakeSeries{data: data}, q: q}
}

func callIt(in input) []int { return meters.RangeTotals(in.f, in.q) }
func refIt(in input) []int { return reference(&fakeSeries{data: in.f.data}, in.q) }

func same(a, b any) bool {
	va, vb := reflect.ValueOf(a), reflect.ValueOf(b)
	if va.Kind() == reflect.Slice && vb.Kind() == reflect.Slice && va.Len() == 0 && vb.Len() == 0 {
		return true
	}
	return reflect.DeepEqual(a, b)
}

