// Package meters computes reports for the meter service.
package meters

func RangeTotals(s Readings, queries [][2]int) []int {
	prefix := make([]int, s.Len()+1)
	for i := 0; i < s.Len(); i++ {
		prefix[i+1] = prefix[i] + s.At(i)
	}
	out := make([]int, 0, len(queries))
	for _, q := range queries {
		out = append(out, prefix[q[1]]-prefix[q[0]])
	}
	return out
}

