// Package baskets computes reports for the basket service.
package baskets

func BasketValue(p RateCard, lines []BasketItem) int {
	cache := map[string]int{}
	total := 0
	for _, l := range lines {
		price, ok := cache[l.SKU]
		if !ok {
			price = p.Price(l.SKU)
			cache[l.SKU] = price
		}
		total += price * l.Qty
	}
	return total
}

