// Package orgtree computes reports for the org chart service.
package orgtree

func Depths(parent ParentOf, nodes []int) []int {
	known := map[int]int{}
	var depthOf func(n int) int
	depthOf = func(n int) int {
		if d, ok := known[n]; ok {
			return d
		}
		d := 0
		if p, ok := parent(n); ok {
			d = depthOf(p) + 1
		}
		known[n] = d
		return d
	}
	out := make([]int, 0, len(nodes))
	for _, n := range nodes {
		out = append(out, depthOf(n))
	}
	return out
}

