func reference(parent orgtree.ParentOf, nodes []int) []int {
	out := make([]int, 0, len(nodes))
	for _, n := range nodes {
		depth := 0
		for cur := n; ; depth++ {
			p, ok := parent(cur)
			if !ok {
				break
			}
			cur = p
		}
		out = append(out, depth)
	}
	return out
