type fakeTree struct {
	p     []int
	calls int
}

func (f *fakeTree) parent(n int) (int, bool) {
	f.calls++
	if n == 0 {
		return 0, false
	}
	return f.p[n], true
}

type input struct {
	f     *fakeTree
	nodes []int
}

