	for i := 1; i < n; i++ {
		lo := i - 30
		if lo < 0 {
			lo = 0
		}
		p[i] = lo + rng.Intn(i-lo)
	}
	nodes := make([]int, n)
	for i := range nodes {
		nodes[i] = i
	}
	return input{f: &fakeTree{p: p}, nodes: nodes}
}

func callIt(in input) []int { return orgtree.Depths(in.f.parent, in.nodes) }
