// Package orders computes reports for the order service.
package orders

func OrderTotal(p Pricing, lines []OrderLine) int {
	cache := map[string]int{}
	total := 0
	for _, l := range lines {
		price, ok := cache[l.SKU]
		if !ok {
			price = p.Price(l.SKU)
			cache[l.SKU] = price
		}
		total += price * l.Qty
	}
	return total
}

